// Generates src/logo-data.ts: the brand logo as 1-bit rasters (ESC/POS GS v 0 row format) for 58 mm and 80 mm
// paper, from public/logo.png. Run by hand when the logo changes:  pnpm --filter @burgerhause/print-agent logo
// The generated file is COMMITTED, so the agent bundle needs no image library at runtime or build time.
//   --preview <dir>   also writes PNG previews of the rasters (to look at them)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const source = path.join(root, "../../public/logo.png");

// Width in dots (multiple of 8). The logo is square, so height = width: ~18 mm (58 mm paper) / ~24 mm (80 mm).
const SIZES = { 58: 144, 80: 192 };

/** Everything outside the logo's white ring is paper, not ink: a black square would waste thermal paper. */
const CIRCLE_RADIUS = 0.93;

async function gray(size) {
  const { data } = await sharp(source)
    .flatten({ background: "#ffffff" })
    .resize(size, size, { fit: "fill", kernel: "lanczos3" })
    .grayscale()
    .normalise()
    .raw()
    .toBuffer({ resolveWithObject: true });
  const px = Float32Array.from(data);
  const c = (size - 1) / 2;
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) if (Math.hypot(x - c, y - c) > c * CIRCLE_RADIUS) px[y * size + x] = 255;
  return px;
}

/** Atkinson dithering: crisp on small thermal rasters (keeps solid areas solid, unlike Floyd-Steinberg). Returns 1 = ink. */
function atkinson(px, size) {
  const out = new Uint8Array(size * size);
  const add = (x, y, v) => {
    if (x >= 0 && x < size && y < size) px[y * size + x] += v;
  };
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const old = px[y * size + x];
      const ink = old < 128;
      out[y * size + x] = ink ? 1 : 0;
      const err = (old - (ink ? 0 : 255)) / 8;
      add(x + 1, y, err); add(x + 2, y, err);
      add(x - 1, y + 1, err); add(x, y + 1, err); add(x + 1, y + 1, err);
      add(x, y + 2, err);
    }
  }
  return out;
}

function pack(bits, size) {
  const bytesPerRow = size / 8;
  const buf = Buffer.alloc(bytesPerRow * size);
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) if (bits[y * size + x]) buf[y * bytesPerRow + (x >> 3)] |= 0x80 >> (x & 7);
  return buf;
}

const previewIdx = process.argv.indexOf("--preview");
const previewDir = previewIdx > 0 ? process.argv[previewIdx + 1] : null;
const entries = [];
for (const [paper, size] of Object.entries(SIZES)) {
  const bits = atkinson(await gray(size), size);
  entries.push(`  ${paper}: { width: ${size}, height: ${size}, data: "${pack(bits, size).toString("base64")}" },`);
  if (previewDir) {
    fs.mkdirSync(previewDir, { recursive: true });
    const rgb = Buffer.alloc(size * size);
    for (let i = 0; i < bits.length; i++) rgb[i] = bits[i] ? 0 : 255;
    await sharp(rgb, { raw: { width: size, height: size, channels: 1 } }).png().toFile(path.join(previewDir, `logo-${paper}.png`));
  }
}

const file = `// GENERATED by scripts/make-logo.mjs from public/logo.png: do not edit by hand.
// 1-bit rasters (1 = ink), rows of width/8 bytes, base64: exactly the data of the ESC/POS GS v 0 command.
export type LogoRaster = { width: number; height: number; data: string };

export const LOGO_RASTERS: Record<58 | 80, LogoRaster> = {
${entries.join("\n")}
};
`;
fs.writeFileSync(path.join(root, "src/logo-data.ts"), file);
console.log("wrote src/logo-data.ts", Object.entries(SIZES).map(([p, s]) => `${p}mm=${s}x${s}`).join(" "));
